"use client";
import {Children,cloneElement,isValidElement,useCallback,useEffect,useRef,useState,type ReactNode} from "react";
import PermissionBoundary from "./permission-boundary";
import LoadingScreen from "./loading-screen";
import LocationWorkspace from "./location-workspace";
import PermissionMatrix from "./permission-matrix";
import OverviewDashboard from "./overview-dashboard";
import UomConversions from "./uom-conversions";
import WarehouseConfig from "./warehouse-config";
import PartnerMaster from "./partner-master";
import { hasPartnerRole } from "./partner-role";
